def bank_search(code, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0392000" if __import__("os").path.isdir("./environment_mix/0392000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")
    tool_name = "bank-search"

    def _stable_json(o):
        return json.dumps(o, ensure_ascii=False, separators=(",", ":"), sort_keys=True)

    def _norm_cache_key(params):
        return f"{tool_name}|{_stable_json(params)}"

    def _new_req_id(reqs):
        rid = "bra_req_" + uuid.uuid4().hex
        taken = {r.get("id") for r in reqs if isinstance(r, dict)}
        while rid in taken:
            rid = "bra_req_" + uuid.uuid4().hex
        return rid

    def _parse_rfc3339_z(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                core = s[:-1]
                if "." in core:
                    d, frac = core.split(".", 1)
                    frac = re.sub(r"[^\d]", "", frac)[:6]
                    core = d + "." + frac
                return datetime.datetime.fromisoformat(core).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _resolve_ambient_client():
        # No explicit credential: choose an active client that can actually call (valid limits)
        clients = _load("api_clients.json")
        candidates = []
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            rpm = c.get("requests_per_minute_limit")
            if not isinstance(rpm, int) or rpm < 1:
                continue
            rpd = c.get("requests_per_day_limit")
            if rpd is not None and (not isinstance(rpd, int) or rpd < 1):
                continue
            candidates.append(c)
        if not candidates:
            return None
        # Prefer higher RPM to reduce rate-limit collisions
        candidates.sort(key=lambda x: x.get("requests_per_minute_limit", 1), reverse=True)
        return candidates[0]

    def _enforce_limits(client):
        reqs = _load("api_requests.json")
        rpm_limit = client.get("requests_per_minute_limit")
        rpd_limit = client.get("requests_per_day_limit")
        cutoff_min = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        in_min = 0
        in_day = 0
        for r in reqs:
            if not isinstance(r, dict) or r.get("client_id") != client.get("id"):
                continue
            dt = _parse_rfc3339_z(r.get("requested_at"))
            if not dt:
                continue
            if dt >= cutoff_min:
                in_min += 1
            if dt >= day_start:
                in_day += 1
        if isinstance(rpm_limit, int) and in_min >= rpm_limit:
            return False, "RATE_LIMIT", 429
        if isinstance(rpd_limit, int) and in_day >= rpd_limit:
            return False, "QUOTA_EXCEEDED", 429
        return True, None, 200

    def _log_request(reqs, client_id, input_params, http_status, error_code=None, cache_hit=False, response_ref=None):
        latency_ms = max(0, int((time.time() - t0) * 1000))
        row = {
            "id": _new_req_id(reqs),
            "client_id": client_id,
            "tool_name": tool_name,
            "input_params": input_params,
            "normalized_cache_key": _norm_cache_key(input_params),
            "cache_hit": bool(cache_hit),
            "http_status": int(http_status),
            "error_code": error_code,
            "latency_ms": latency_ms,
            "response_ref": response_ref,
            "requested_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    # Validate inputs (and ensure "exactly" the schema fields: only code)
    input_params = {"code": code}
    if not isinstance(code, str) or not code.strip():
        # log requires a client; pick ambient
        client = _resolve_ambient_client()
        if not client:
            return _err("UNAUTHORIZED", "No active client is available to serve this request.")
        reqs = _load("api_requests.json")
        _log_request(reqs, client.get("id"), input_params, 400, "VALIDATION_ERROR", cache_hit=False, response_ref=None)
        return _err("VALIDATION_ERROR", "Parameter 'code' is required and must be a non-empty string.")
    code_norm = code.strip()

    client = _resolve_ambient_client()
    if not client:
        return _err("UNAUTHORIZED", "No active client is available to serve this request.")

    # enforce client status (should be active already)
    if client.get("status") != "active":
        reqs = _load("api_requests.json")
        http_status = 403 if client.get("status") in ("suspended", "revoked") else 401
        _log_request(reqs, client.get("id"), {"code": code_norm}, http_status, "UNAUTHORIZED", cache_hit=False, response_ref=None)
        return _err("UNAUTHORIZED", "Client is not allowed to perform this operation.", client_status=client.get("status"))

    ok, ecode, http_status = _enforce_limits(client)
    if not ok:
        reqs = _load("api_requests.json")
        _log_request(reqs, client.get("id"), {"code": code_norm}, http_status, ecode, cache_hit=False, response_ref=None)
        return _err(ecode, "Rate limit or quota exceeded.")

    # Lookup: accept any non-empty code string; match exact stored bank_code
    finance = _load("reference_finance.json")
    match = None
    for r in finance:
        if not isinstance(r, dict):
            continue
        if r.get("entity_type") != "bank":
            continue
        if r.get("status") != "active":
            continue
        if r.get("bank_code") == code_norm:
            match = r
            break

    reqs = _load("api_requests.json")
    if not match:
        _log_request(reqs, client.get("id"), {"code": code_norm}, 404, "NOT_FOUND", cache_hit=False, response_ref=None)
        return _err("NOT_FOUND", "No bank matches the provided code.")

    _log_request(reqs, client.get("id"), {"code": code_norm}, 200, None, cache_hit=True, response_ref={"bank_id": match.get("id")})
    return {"bank": match}

def bank_list(limit=None, cursor=None, sort=None, status=None, **_extra):
    import json, os, datetime, time, base64, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0392000" if __import__("os").path.isdir("./environment_mix/0392000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")
    tool_name = "bank-list"
    allowed_sort = {"bank_code", "-bank_code", "bank_name", "-bank_name"}
    allowed_status = {"active", "inactive", "superseded"}

    def _stable_json(o):
        return json.dumps(o, ensure_ascii=False, separators=(",", ":"), sort_keys=True)

    def _norm_cache_key(params):
        return f"{tool_name}|{_stable_json(params)}"

    def _new_req_id(reqs):
        rid = "bra_req_" + uuid.uuid4().hex
        taken = {r.get("id") for r in reqs if isinstance(r, dict)}
        while rid in taken:
            rid = "bra_req_" + uuid.uuid4().hex
        return rid

    def _parse_rfc3339_z(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                core = s[:-1]
                if "." in core:
                    d, frac = core.split(".", 1)
                    frac = re.sub(r"[^\d]", "", frac)[:6]
                    core = d + "." + frac
                return datetime.datetime.fromisoformat(core).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _resolve_ambient_client():
        clients = _load("api_clients.json")
        candidates = []
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            rpm = c.get("requests_per_minute_limit")
            if not isinstance(rpm, int) or rpm < 1:
                continue
            rpd = c.get("requests_per_day_limit")
            if rpd is not None and (not isinstance(rpd, int) or rpd < 1):
                continue
            candidates.append(c)
        if not candidates:
            return None
        candidates.sort(key=lambda x: x.get("requests_per_minute_limit", 1), reverse=True)
        return candidates[0]

    def _enforce_limits(client):
        reqs = _load("api_requests.json")
        rpm_limit = client.get("requests_per_minute_limit")
        rpd_limit = client.get("requests_per_day_limit")
        cutoff_min = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        in_min = 0
        in_day = 0
        for r in reqs:
            if not isinstance(r, dict) or r.get("client_id") != client.get("id"):
                continue
            dt = _parse_rfc3339_z(r.get("requested_at"))
            if not dt:
                continue
            if dt >= cutoff_min:
                in_min += 1
            if dt >= day_start:
                in_day += 1
        if isinstance(rpm_limit, int) and in_min >= rpm_limit:
            return False, "RATE_LIMIT", 429
        if isinstance(rpd_limit, int) and in_day >= rpd_limit:
            return False, "QUOTA_EXCEEDED", 429
        return True, None, 200

    def _log_request(reqs, client_id, input_params, http_status, error_code=None, cache_hit=False, response_ref=None):
        latency_ms = max(0, int((time.time() - t0) * 1000))
        row = {
            "id": _new_req_id(reqs),
            "client_id": client_id,
            "tool_name": tool_name,
            "input_params": input_params,
            "normalized_cache_key": _norm_cache_key(input_params),
            "cache_hit": bool(cache_hit),
            "http_status": int(http_status),
            "error_code": error_code,
            "latency_ms": latency_ms,
            "response_ref": response_ref,
            "requested_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    # Defaults per schema-like behavior
    if limit is None:
        limit_val = 100
    else:
        limit_val = limit

    if sort is None:
        sort_val = "bank_code"
    else:
        sort_val = sort

    if status is None:
        status_val = "active"
    else:
        status_val = status

    input_params = {"limit": limit_val, "cursor": cursor, "sort": sort_val, "status": status_val}

    client = _resolve_ambient_client()
    if not client:
        return _err("UNAUTHORIZED", "No active client is available to serve this request.")

    # Validate
    if not isinstance(limit_val, int) or limit_val < 1 or limit_val > 500:
        reqs = _load("api_requests.json")
        _log_request(reqs, client.get("id"), input_params, 400, "VALIDATION_ERROR", cache_hit=False, response_ref=None)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
    if sort_val not in allowed_sort:
        reqs = _load("api_requests.json")
        _log_request(reqs, client.get("id"), input_params, 400, "VALIDATION_ERROR", cache_hit=False, response_ref=None)
        return _err("VALIDATION_ERROR", "sort must be one of: bank_code, -bank_code, bank_name, -bank_name.")
    if status_val not in allowed_status:
        reqs = _load("api_requests.json")
        _log_request(reqs, client.get("id"), input_params, 400, "VALIDATION_ERROR", cache_hit=False, response_ref=None)
        return _err("VALIDATION_ERROR", "status must be one of: active, inactive, superseded.")
    if cursor is not None and not isinstance(cursor, str):
        reqs = _load("api_requests.json")
        _log_request(reqs, client.get("id"), input_params, 400, "VALIDATION_ERROR", cache_hit=False, response_ref=None)
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # enforce status
    if client.get("status") != "active":
        reqs = _load("api_requests.json")
        http_status = 403 if client.get("status") in ("suspended", "revoked") else 401
        _log_request(reqs, client.get("id"), input_params, http_status, "UNAUTHORIZED", cache_hit=False, response_ref=None)
        return _err("UNAUTHORIZED", "Client is not allowed to perform this operation.", client_status=client.get("status"))

    ok, ecode, http_status = _enforce_limits(client)
    if not ok:
        reqs = _load("api_requests.json")
        _log_request(reqs, client.get("id"), input_params, http_status, ecode, cache_hit=False, response_ref=None)
        return _err(ecode, "Rate limit or quota exceeded.")

    # Fetch & filter
    finance = _load("reference_finance.json")
    rows = [r for r in finance if isinstance(r, dict) and r.get("entity_type") == "bank" and r.get("status") == status_val]

    # Sort
    reverse = False
    key = sort_val
    if sort_val.startswith("-"):
        reverse = True
        key = sort_val[1:]

    def _k(r):
        v = r.get(key)
        return "" if v is None else str(v)

    rows.sort(key=_k, reverse=reverse)

    # Cursor: accept either our encoded cursor or a raw id (to be tolerant)
    start = 0
    if cursor:
        decoded = None
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
        except Exception:
            decoded = cursor
        # decoded format: "idx:<n>" or "after_id:<id>"
        m = re.match(r"^idx:(\d+)$", decoded or "")
        if m:
            start = int(m.group(1))
        else:
            m2 = re.match(r"^after_id:(.+)$", decoded or "")
            if m2:
                after_id = m2.group(1)
                pos = None
                for i, r in enumerate(rows):
                    if r.get("id") == after_id:
                        pos = i
                        break
                if pos is None:
                    reqs = _load("api_requests.json")
                    _log_request(reqs, client.get("id"), input_params, 400, "VALIDATION_ERROR", cache_hit=False, response_ref=None)
                    return _err("VALIDATION_ERROR", "cursor is invalid.")
                start = pos + 1
            else:
                # also allow cursor to be a bank id directly
                pos = None
                for i, r in enumerate(rows):
                    if r.get("id") == decoded:
                        pos = i
                        break
                if pos is None:
                    reqs = _load("api_requests.json")
                    _log_request(reqs, client.get("id"), input_params, 400, "VALIDATION_ERROR", cache_hit=False, response_ref=None)
                    return _err("VALIDATION_ERROR", "cursor is invalid.")
                start = pos + 1

    page = rows[start:start + limit_val]
    next_cursor = None
    has_more = start + limit_val < len(rows)
    if has_more:
        payload = f"idx:{start + limit_val}"
        next_cursor = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8")

    reqs = _load("api_requests.json")
    _log_request(reqs, client.get("id"), input_params, 200, None, cache_hit=True, response_ref={"returned": len(page), "total": len(rows)})
    return {"banks": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

def ddd_info(ddd, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0392000" if __import__("os").path.isdir("./environment_mix/0392000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")
    tool_name = "ddd-info"

    def _new_req_id(reqs):
        rid = "bra_req_" + uuid.uuid4().hex
        taken = {r.get("id") for r in reqs if isinstance(r, dict)}
        while rid in taken:
            rid = "bra_req_" + uuid.uuid4().hex
        return rid

    def _stable_json(o):
        return json.dumps(o, ensure_ascii=False, separators=(",", ":"), sort_keys=True)

    def _norm_cache_key(params):
        return f"{tool_name}|{_stable_json(params)}"

    def _parse_rfc3339_z(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                core = s[:-1]
                if "." in core:
                    d, frac = core.split(".", 1)
                    frac = re.sub(r"[^\d]", "", frac)[:6]
                    core = d + "." + frac
                return datetime.datetime.fromisoformat(core).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _pick_active_client():
        clients = _load("api_clients.json")
        best = None
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            rpm = c.get("requests_per_minute_limit")
            if not isinstance(rpm, int) or rpm < 1:
                continue
            rpd = c.get("requests_per_day_limit")
            if rpd is not None and (not isinstance(rpd, int) or rpd < 1):
                continue
            if best is None or rpm > best.get("requests_per_minute_limit", 0):
                best = c
        return best

    def _check_quota_and_rate(client):
        rpm = client.get("requests_per_minute_limit")
        rpd = client.get("requests_per_day_limit")
        reqs = _load("api_requests.json")

        cutoff_min = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)

        in_min = 0
        in_day = 0
        cid = client.get("id")
        for r in reqs:
            if not isinstance(r, dict) or r.get("client_id") != cid:
                continue
            dt = _parse_rfc3339_z(r.get("requested_at"))
            if not dt:
                continue
            if dt >= cutoff_min:
                in_min += 1
            if dt >= day_start:
                in_day += 1

        if isinstance(rpm, int) and in_min >= rpm:
            return _err("RATE_LIMIT", "Too many requests."), 429
        if rpd is not None and isinstance(rpd, int) and in_day >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded."), 429
        return None, None

    def _log(client_id, input_params, cache_hit, http_status, error_code=None, response_ref=None):
        reqs = _load("api_requests.json")
        rid = _new_req_id(reqs)
        latency_ms = max(0, int((time.time() - t0) * 1000))
        row = {
            "id": rid,
            "client_id": client_id,
            "tool_name": tool_name,
            "input_params": input_params,
            "normalized_cache_key": _norm_cache_key(input_params),
            "cache_hit": bool(cache_hit),
            "http_status": int(http_status),
            "error_code": error_code,
            "latency_ms": latency_ms,
            "response_ref": response_ref,
            "requested_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)
        return rid

    client = _pick_active_client()
    if not client:
        return _err("UNAUTHORIZED", "No active API client available to authorize this request", http_status=401)

    # Validate input
    if not isinstance(ddd, str):
        _log(client.get("id"), {"ddd": ddd}, False, 400, "VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "Parameter 'ddd' must be a string matching ^\\d{2}$.")
    ddd_norm = ddd.strip()
    if not re.fullmatch(r"^\d{2}$", ddd_norm):
        _log(client.get("id"), {"ddd": ddd_norm}, False, 400, "VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "Parameter 'ddd' must be exactly 2 digits.")

    limit_err, http_status = _check_quota_and_rate(client)
    if limit_err:
        _log(client.get("id"), {"ddd": ddd_norm}, False, http_status, limit_err["error"]["code"], None)
        return limit_err

    if client.get("status") != "active":
        _log(client.get("id"), {"ddd": ddd_norm}, False, 403, "UNAUTHORIZED", None)
        return _err("UNAUTHORIZED", "Client is not allowed to perform requests.", http_status=403)

    geo = _load("reference_geo.json")
    rec = next((
        r for r in geo
        if isinstance(r, dict)
        and r.get("entity_type") == "ddd"
        and r.get("status") == "active"
        and str(r.get("ddd", "")) == ddd_norm
    ), None)

    if not rec:
        _log(client.get("id"), {"ddd": ddd_norm}, False, 404, "NOT_FOUND", None)
        return _err("NOT_FOUND", "DDD not found in reference dataset.")

    out = {
        "ddd": ddd_norm,
        "state": rec.get("state_uf"),
        "cities": rec.get("ddd_cities") if isinstance(rec.get("ddd_cities"), list) else [],
        "record": rec
    }
    _log(client.get("id"), {"ddd": ddd_norm}, True, 200, None, {"geo_id": rec.get("id")})
    return out

