    if not ok:
        reqs = _load("api_requests.json")
        _log_request(reqs, client.get("id"), input_params, http_status, ecode, cache_hit=False, response_ref=None)
        return _err(ecode, "Rate limit or quota exceeded.")

    geo = _load("reference_geo.json")
    rows = [r for r in geo if isinstance(r, dict) and r.get("entity_type") == "state" and r.get("status") == status_val]

    reverse = False
    key = sort_val
    if sort_val.startswith("-"):
        reverse = True
        key = sort_val[1:]

    def _k(r):
        v = r.get(key)
        return "" if v is None else str(v)

    rows.sort(key=_k, reverse=reverse)

    start = 0
    if cursor:
        decoded = None
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
        except Exception:
            decoded = cursor
        m = re.match(r"^idx:(\d+)$", decoded or "")
        if m:
            start = int(m.group(1))
        else:
            m2 = re.match(r"^after_id:(.+)$", decoded or "")
            if m2:
                after_id = m2.group(1)
                pos = None
                for i, r in enumerate(rows):
                    if r.get("id") == after_id:
                        pos = i
                        break
                if pos is None:
                    reqs = _load("api_requests.json")
                    _log_request(reqs, client.get("id"), input_params, 400, "VALIDATION_ERROR", cache_hit=False, response_ref=None)
                    return _err("VALIDATION_ERROR", "cursor is invalid.")
                start = pos + 1
            else:
                pos = None
                for i, r in enumerate(rows):
                    if r.get("id") == decoded:
                        pos = i
                        break
                if pos is None:
                    reqs = _load("api_requests.json")
                    _log_request(reqs, client.get("id"), input_params, 400, "VALIDATION_ERROR", cache_hit=False, response_ref=None)
                    return _err("VALIDATION_ERROR", "cursor is invalid.")
                start = pos + 1

    page = rows[start:start + limit_val]
    has_more = start + limit_val < len(rows)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"idx:{start + limit_val}".encode("utf-8")).decode("utf-8")

    reqs = _load("api_requests.json")
    _log_request(reqs, client.get("id"), input_params, 200, None, cache_hit=True, response_ref={"returned": len(page), "total": len(rows)})
    return {"states": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

